import React, { useEffect, useState } from "react";
import axios from "axios";
import AppShell from "./ui/AppShell";
import Panel from "./ui/Panel";
import StatCard from "./ui/StatCard";
import { FaBrain, FaClock, FaTasks, FaCalendarAlt } from "react-icons/fa";
import "./theme.css";

function SmartPlannerAdvanced() {
  const userId = localStorage.getItem("user_id");

  const [plans, setPlans] = useState([]);
  const [targets, setTargets] = useState([]);

  const loadData = async () => {
    const p = await axios.get(`http://127.0.0.1:8000/planner/${userId}`);
    setPlans(p.data.plans || []);

    const t = await axios.get(`http://127.0.0.1:8000/smart-target/${userId}`);
    setTargets(t.data.targets || []);
  };

  const generatePlan = async () => {
    await axios.post(`http://127.0.0.1:8000/smart-auto-plan/${userId}`);
    loadData();
  };

  useEffect(() => {
    loadData();
  }, []);

  return (
    <AppShell
      title="Smart Planner"
      subtitle="AI-based automatic study scheduling using deadlines"
      action={
        <button className="btn btn-primary" onClick={generatePlan}>
          Generate Smart Plan
        </button>
      }
    >
      <div className="page-grid-4" style={{ marginBottom: "18px" }}>
        <StatCard
          icon={<FaBrain />}
          label="AI Mode"
          value="Active"
        />
        <StatCard
          icon={<FaTasks />}
          label="Total Plans"
          value={plans.length}
        />
        <StatCard
          icon={<FaClock />}
          label="Pending"
          value={plans.filter(p => p.status === "Pending").length}
        />
        <StatCard
          icon={<FaCalendarAlt />}
          label="Today Tasks"
          value={plans.filter(p =>
            p.study_date === new Date().toISOString().split("T")[0]
          ).length}
        />
      </div>

      <div className="page-grid-2">

        <Panel title="Smart Targets">
          {targets.map((t, i) => (
            <div className="list-card" key={i}>
              <h4>{t.course_title}</h4>
              <div className="muted">
                Topics/day: {t.target_topics_per_day}
              </div>
              <div className="muted">
                Hours/day: {t.recommended_hours_per_day}
              </div>
              <div className="muted">
                Remaining: {t.remaining_topics}
              </div>
            </div>
          ))}
        </Panel>

        <Panel title="Generated Plan">
          {plans.map((p) => {
            const isExpired = new Date(p.study_date) < new Date();

            return (
              <div className="list-card" key={p.id}>
                <h4>{p.topic}</h4>
                <div className="muted">{p.study_date}</div>

                <div style={{ marginTop: "10px" }}>
                  {p.status === "Completed" && (
                    <span className="badge badge-green">Done</span>
                  )}
                  {p.status === "Pending" && !isExpired && (
                    <span className="badge badge-purple">Pending</span>
                  )}
                  {isExpired && (
                    <span className="badge badge-red">Overdue</span>
                  )}
                </div>
              </div>
            );
          })}
        </Panel>

      </div>
    </AppShell>
  );
}

export default SmartPlannerAdvanced;
